// 使用原生 fetch，和测试页保持完全一致
const BASE = '/api'

function request(url, options) {
  var token = localStorage.getItem('token')
  var headers = options.headers || {}
  if (token) headers['Authorization'] = 'Bearer ' + token
  if (options.body && typeof options.body === 'object') {
    headers['Content-Type'] = 'application/json'
    options.body = JSON.stringify(options.body)
  }
  var fetchOptions = {
    method: options.method || 'GET',
    headers: headers,
    cache: 'no-store'
  }
  if (options.body) fetchOptions.body = options.body
  return fetch(BASE + url, fetchOptions).then(function(res) {
    return res.json().then(function(data) {
      if (data.code !== 200) {
        var err = new Error(data.message || 'error')
        err.data = data
        throw err
      }
      return data
    })
  })
}

export default {
  get: function(url, params) {
    var qs = ''
    if (params) {
      var arr = []
      for (var k in params) {
        if (params[k] !== undefined && params[k] !== null) arr.push(k + '=' + encodeURIComponent(params[k]))
      }
      if (arr.length) qs = '?' + arr.join('&')
    }
    return request(url + qs, { method: 'GET' })
  },
  post: function(url, data) {
    return request(url, { method: 'POST', body: data })
  },
  put: function(url, data) {
    return request(url, { method: 'PUT', body: data })
  },
  delete: function(url) {
    return request(url, { method: 'DELETE' })
  }
}
